        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, pre, build = match.groups()
    prerelease = tuple(pre.split(".")) if pre else ()
    if any(len(i) > 1 and i[0] == "0" and _numeric(i) for i in prerelease):
        raise ValueError(f"invalid version: {text!r}")
    return Version(int(major), int(minor), int(patch), prerelease, tuple(build.split(".")) if build else ())


def _numeric(ident: str) -> bool:
    return all("0" <= c <= "9" for c in ident)


def _version(v: str | Version) -> Version:
    return v if isinstance(v, Version) else parse(v)


def _cmp(a, b) -> int:
    return (a > b) - (a < b)


