        return c >= 0 and compare(version, upper) < 0
    if op == "~":
        return c >= 0 and compare(version, Version(v.major, v.minor + 1, 0)) < 0
    return {"=": c == 0, ">": c > 0, ">=": c >= 0, "<": c < 0, "<=": c <= 0}[op]

