    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _version(a), _version(b)
    core = _cmp((a.major, a.minor, a.patch), (b.major, b.minor, b.patch))
    return core or _compare_prerelease(a.prerelease, b.prerelease)


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    version = _version(version)
    sets = [[_comparator(c) for c in part.split()] for part in range_.split("||")]
    if not all(sets):
        raise ValueError(f"invalid range: {range_!r}")
    return any(_satisfies_set(version, s) for s in sets)


def _comparator(text: str) -> tuple[str, Version]:
    op, rest = _COMPARATOR.fullmatch(text).groups()
    return op or "=", parse(rest)


def _satisfies_set(version: Version, comparators: list[tuple[str, Version]]) -> bool:
    core = (version.major, version.minor, version.patch)
    if version.prerelease and not any(
        v.prerelease and (v.major, v.minor, v.patch) == core for _, v in comparators
    ):
        return False
    return all(_satisfies_comparator(version, op, v) for op, v in comparators)


def _satisfies_comparator(version: Version, op: str, v: Version) -> bool:
    c = compare(version, v)
    if op == "^":
        if v.major:
            upper = Version(v.major + 1, 0, 0)
        elif v.minor:
            upper = Version(0, v.minor + 1, 0)
        else:
            upper = Version(0, 0, v.patch + 1)
        return c >= 0 and compare(version, upper) < 0
    if op == "~":
        return c >= 0 and compare(version, Version(v.major, v.minor + 1, 0)) < 0
    return {"=": c == 0, ">": c > 0, ">=": c >= 0, "<": c < 0, "<=": c <= 0}[op]
